const rs=await Promise.allSettled(["game-013-log.json","game-013.sgf","game-013.md","AGENTS.md"].map(path=>tools.mcp__desk__read_file({path})));
for(let i=0;i<rs.length;i++){const r=rs[i];if(r.status!=="fulfilled"||r.value.isError)throw new Error("Saved file read failed: "+i);}
const body=r=>r.value.content.filter(c=>c.type==="text").map(c=>c.text).join("\n");
const saved=JSON.parse(body(rs[0]));const sgf=body(rs[1]);const nodeCount=(sgf.match(/;[BW]\[/g)||[]).length;const passCount=(sgf.match(/;[BW]\[\]/g)||[]).length;
if(saved.moves.length!==89||nodeCount!==89||passCount!==4||saved.responses.length!==45||saved.finalCount.B!==47||saved.finalCount.W!==34)throw new Error("Record verification mismatch");
if(!body(rs[3]).includes("three wins and six losses")||!body(rs[2]).includes("Correct count: 27"))throw new Error("Review verification mismatch");
text({savedRecordsVerified:true,moves:nodeCount,passes:passCount,result:saved.metadata.result,finalArea:saved.finalCount});

